editManager::editManager(void) {
    m_viewX = 0;
    m_viewY = 0;
    m_cursorX = 0;
    m_cursorY = 0;
    m_lastHoverId = WIDGET_ID_NONE;
    m_dispatchMask = EDIT_MANAGER_DISPATCH_MASK;
    gNextObjectId = 1;
    m_zoomedOut = EDIT_ZOOM_OUT;
    ResetArea(0, 0, MAP_CELL_GRID_SIZE, MAP_CELL_GRID_SIZE);
    SaveUndo();
    gMapHeader = EDIT_MAP_HEADER();
    m_animationFrame = 0;
    m_tool = EDIT_TOOL_NONE;
    m_toolManager = NULL;
    m_mapChanged = 0;
    m_placedX = m_placedY = EDIT_NO_CELL;
    m_extraCount = MAP_EXTRA_FIRST_RECORD;
    m_placedState = -1;
}

void editManager::LoadObjectIcons(
    i16 tileset,
    char* largeName,
    char* smallName
) {
    m_objectIcons[tileset][EDIT_ZOOM_NORMAL] = gResourceManager->GetIcon(largeName);
    m_objectIcons[tileset][EDIT_ZOOM_OUT] = gResourceManager->GetIcon(smallName);
}

i16 editManager::Open(i16 priority) {
    bitmap* borderImage;
    i32 i;

    NewMap(false);
    borderImage = gResourceManager->GetBitmap("bordedit.bmp");
    BlitBitmapToScreen(borderImage, 0, 0, LOGICAL_SCREEN_WIDTH, LOGICAL_SCREEN_HEIGHT, 0, 0);
    gResourceManager->Dispose(borderImage);
    m_statusFont = gResourceManager->GetFont("smalfont.fnt");
    m_window = new heroWindow(0, 0, "editwind.bin");
    m_horizontalTrack = new iconWidget(
        32,
        464,
        416,
        16,
        "escroll.icn",
        EDIT_SCROLL_HORIZONTAL_TRACK,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_HORIZONTAL_TRACK,
        ICON_WIDGET_DRAW,
        1
    );
    m_verticalTrack = new iconWidget(
        464,
        32,
        16,
        416,
        "escroll.icn",
        EDIT_SCROLL_VERTICAL_TRACK,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_VERTICAL_TRACK,
        ICON_WIDGET_DRAW,
        1
    );
    m_horizontalKnob = new iconWidget(
        EDIT_KNOB_FIRST,
        468,
        17,
        8,
        "escroll.icn",
        EDIT_SCROLL_HORIZONTAL_KNOB,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_HORIZONTAL_KNOB,
        ICON_WIDGET_DRAW,
        1
    );
    m_verticalKnob = new iconWidget(
        468,
        EDIT_KNOB_FIRST,
        8,
        17,
        "escroll.icn",
        EDIT_SCROLL_VERTICAL_KNOB,
        ICON_DRAW_NORMAL,
        EDIT_CONTROL_VERTICAL_KNOB,
        ICON_WIDGET_DRAW,
        1
    );
    m_window->AddWidget(m_horizontalTrack, WINDOW_Z_ORDER_APPEND);
    m_window->AddWidget(m_verticalTrack, WINDOW_Z_ORDER_APPEND);
    m_window->AddWidget(m_horizontalKnob, WINDOW_Z_ORDER_APPEND);
    m_window->AddWidget(m_verticalKnob, WINDOW_Z_ORDER_APPEND);
    gWindowManager->AddWindow(m_window, WINDOW_Z_ORDER_APPEND, 1);
    m_groundTiles[EDIT_ZOOM_NORMAL] = gResourceManager->GetTileset("ground32.til");
    m_groundTiles[EDIT_ZOOM_OUT] = gResourceManager->GetTileset("ground16.til");
    m_cloudTiles[EDIT_ZOOM_NORMAL] = gResourceManager->GetTileset("clof32.til");
    m_cloudTiles[EDIT_ZOOM_OUT] = gResourceManager->GetTileset("clof16.til");
    for (i = 0; i < EDIT_MANAGER_TILESET_COUNT; i++)
        m_objectIcons[i][EDIT_ZOOM_NORMAL] =
            m_objectIcons[i][EDIT_ZOOM_OUT] = NULL;
    LoadObjectIcons(TILESET_OBJ32_00, "obj32-00.icn", "obj16-00.icn");
    LoadObjectIcons(TILESET_OBJ32_01, "obj32-01.icn", "obj16-01.icn");
    LoadObjectIcons(TILESET_OBJ32_02, "obj32-02.icn", "obj16-02.icn");
    LoadObjectIcons(TILESET_OBJ32_03, "obj32-03.icn", "obj16-03.icn");
    LoadObjectIcons(TILESET_OBJ32_04, "obj32-04.icn", "obj16-04.icn");
    LoadObjectIcons(TILESET_OBJ32_05, "obj32-05.icn", "obj16-05.icn");
    LoadObjectIcons(TILESET_OBJ32_06, "obj32-06.icn", "obj16-06.icn");
    LoadObjectIcons(TILESET_OBJ32_07, "obj32-07.icn", "obj16-07.icn");
    LoadObjectIcons(TILESET_MTN32, "mtn32.icn", "mtn16.icn");
    LoadObjectIcons(TILESET_TREE32, "tree32.icn", "tree16.icn");
    LoadObjectIcons(TILESET_TOWN32, "town32.icn", "town16.icn");
    LoadObjectIcons(TILESET_RSRC32, "rsrc32.icn", "rsrc16.icn");
    LoadObjectIcons(TILESET_MONS32, "mons32.icn", "mons16.icn");
    LoadObjectIcons(TILESET_ART32, "art32.icn", "art16.icn");
    m_buttons = gResourceManager->GetIcon("buttons.icn");
    m_window->DrawWindow(0);
    DrawRadar(true);
    DrawView(m_viewX, m_viewY);
    UpdateMapView();
    gMouseManager->SetPointer("editor.mse", EDIT_POINTER_DEFAULT);
    gMouseManager->WarpPointer(LOGICAL_SCREEN_WIDTH / 2, 200);
    gMouseManager->ReallyShowPointer();
    gMouseManager->NewUpdate(true);
    m_messageMask = BASE_MANAGER_ACCEPT_EXECUTIVE;
    m_priority = priority;
    m_active = 1;
    strcpy(m_name, "editManager");
    SelectTool(EDIT_TOOL_TERRAIN);
    return BASE_MANAGER_SUCCESS;
}

void editManager::Close(void) {
    i32 i;

    NewMap(false);
    ClearErrors();
    SelectTool(EDIT_TOOL_NONE);
    gWindowManager->RemoveWindow(m_window);
    delete m_window;
    gResourceManager->Dispose(m_groundTiles[EDIT_ZOOM_NORMAL]);
    gResourceManager->Dispose(m_groundTiles[EDIT_ZOOM_OUT]);
    gResourceManager->Dispose(m_cloudTiles[EDIT_ZOOM_NORMAL]);
    gResourceManager->Dispose(m_cloudTiles[EDIT_ZOOM_OUT]);
    for (i = 0; i < EDIT_MANAGER_TILESET_COUNT; i++) {
        gResourceManager->Dispose(m_objectIcons[i][EDIT_ZOOM_NORMAL]);
        gResourceManager->Dispose(m_objectIcons[i][EDIT_ZOOM_OUT]);
    }
    gResourceManager->Dispose(m_buttons);
    gResourceManager->Dispose(m_statusFont);
    gMouseManager->SetPointer(MOUSE_INVALID_CURSOR_FRAME);
    m_active = 0;
}

i16 editManager::Main(tag_message& message) {
    i32 spare1;
    i32 spare2;
    i32 helpIndex;
    editMap* swap;

    if (!(message.type & m_dispatchMask)) {
        if (message.type) {
            message.type = MESSAGE_NONE;
            return MESSAGE_DISPATCH_FORWARD;
        }
        return MESSAGE_DISPATCH_CONTINUE;
    }
    helpIndex = EDIT_BUTTON_HELP_NONE;
    switch (message.type) {
        case MESSAGE_WIDGET:
            switch (message.command) {
                case WIDGET_NOTIFY_DESELECT:
                    if (message.modifiers & MESSAGE_MODIFIER_RIGHT_BUTTON)
                        break;
                    switch (message.id) {
                        case EDIT_CONTROL_TERRAIN:
                            SelectTool(EDIT_TOOL_TERRAIN);
                            break;
                        case EDIT_CONTROL_OBJECTS:
                            SelectTool(EDIT_TOOL_OBJECTS);
                            break;
                        case EDIT_CONTROL_DETAILS:
                            SelectTool(EDIT_TOOL_DETAILS);
                            break;
                        case EDIT_CONTROL_ERASER:
                            SelectTool(EDIT_TOOL_ERASER);
                            break;
                        case EDIT_CONTROL_LOAD:
                            if (!PickMap("", "map", FILE_REQUESTER_LOAD))
                                break;
                            if (!(LoadMap(m_mapFileName))) {
                                m_mapChanged = 0;
                                m_placedX = m_placedY = EDIT_NO_CELL;
                            }
                            m_viewX = m_viewY = 0;
                            m_window->DrawWindow(0);
                            DrawRadar(true);
                            DrawMap();
                            UpdateMapView();
                            break;
                        case EDIT_CONTROL_SAVE:
                            if (!(SaveMap(m_mapFileName))) {
                                sprintf(
                                    gText,
                                    localization::Tr("editor.map.saved"),
                                    gMapHeader->name[0]
                                );
                                NormalDialog(gText, NORMAL_DIALOG_TYPE_OK);
                                m_mapChanged = 0;
                                m_placedX = m_placedY = EDIT_NO_CELL;
                            }
                            break;
                        case EDIT_CONTROL_ZOOM:
                            ToggleZoom();
                            break;
                        case EDIT_CONTROL_QUIT:
                            if (Confirm(localization::Tr("editor.quit.confirm")) == 1)
                                ShutDown(NULL);
                            else
                                return MESSAGE_DISPATCH_CONSUME;
                            break;
                        case EDIT_CONTROL_MAP_INFO:
                            MapDetailsDialog(false);
                            break;
                        case EDIT_CONTROL_RANDOM_MAP:
                            GenerateRandomMap();
                            break;
                        case EDIT_CONTROL_NEW:
                            if (Confirm(localization::Tr("editor.map.new.confirm"))) {
                                ResetArea(0, 0, MAP_CELL_GRID_SIZE, MAP_CELL_GRID_SIZE);
                                NewMap(false);
                                DrawMap();
                                UpdateMapView();
                                DrawRadar(true);
                            }
                            break;
                        case EDIT_CONTROL_UNDO:
                            swap = static_cast<editMap*>(malloc(sizeof(editMap)));
                            memcpy(swap, &m_map, sizeof(editMap));
                            memcpy(&m_map, &m_undoMap, sizeof(editMap));
                            memcpy(&m_undoMap, swap, sizeof(editMap));
                            free(swap);
                            DrawView(m_viewX, m_viewY);
                            UpdateMapView();
                            DrawRadar(true);
                            break;
                        case EDIT_CONTROL_SCROLL_UP:
                            Scroll(0, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN:
                            Scroll(0, 1);
                            break;
                        case EDIT_CONTROL_SCROLL_RIGHT:
                            Scroll(1, 0);
                            break;
                        case EDIT_CONTROL_SCROLL_LEFT:
                            Scroll(-1, 0);
                            break;
                        case EDIT_CONTROL_SCROLL_UP_LEFT:
                            Scroll(-1, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_UP_RIGHT:
                            Scroll(1, -1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_LEFT:
                            Scroll(-1, 1);
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_RIGHT:
                            Scroll(1, 1);
                            break;
                    }
                    break;
                case WIDGET_NOTIFY_RIGHT_CLICK:
                    switch (message.id) {
                        case EDIT_CONTROL_SCROLL_UP:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_RIGHT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_LEFT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_UP_LEFT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_UP_RIGHT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_LEFT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_SCROLL_DOWN_RIGHT:
                            helpIndex = EDIT_BUTTON_HELP_SCROLL;
                            break;
                        case EDIT_CONTROL_ZOOM:
                            helpIndex = EDIT_BUTTON_HELP_ZOOM;
                            break;
                        case EDIT_CONTROL_UNDO:
                            helpIndex = EDIT_BUTTON_HELP_UNDO;
                            break;
                        case EDIT_CONTROL_MAP_INFO:
                            helpIndex = EDIT_BUTTON_HELP_MAP_INFO;
                            break;
                        case EDIT_CONTROL_NEW:
                            helpIndex = EDIT_BUTTON_HELP_NEW;
                            break;
                        case EDIT_CONTROL_LOAD:
                            helpIndex = EDIT_BUTTON_HELP_LOAD;
                            break;
                        case EDIT_CONTROL_SAVE:
                            helpIndex = EDIT_BUTTON_HELP_SAVE;
                            break;
                        case EDIT_CONTROL_QUIT:
                            helpIndex = EDIT_BUTTON_HELP_QUIT;
                            break;
                        case EDIT_CONTROL_RANDOM_MAP:
                            helpIndex = EDIT_BUTTON_HELP_RANDOM_MAP;
                            break;
                    }
                    if (helpIndex >= 0)
                        NormalDialog(gEditButtonHelp[helpIndex], NORMAL_DIALOG_TYPE_QUICK_VIEW);
                    break;
                case WIDGET_NOTIFY_SELECT:
                    if (message.modifiers & MESSAGE_MODIFIER_RIGHT_BUTTON) {
                        switch (message.id) {
                            case EDIT_CONTROL_RADAR:
                                helpIndex = EDIT_AREA_HELP_RADAR;
                                break;
                            case EDIT_CONTROL_HORIZONTAL_TRACK:
                                helpIndex = EDIT_AREA_HELP_SCROLLING;
                                break;
                            case EDIT_CONTROL_HORIZONTAL_KNOB:
                                helpIndex = EDIT_AREA_HELP_SCROLLING;
                                break;
                            case EDIT_CONTROL_VERTICAL_TRACK:
                                helpIndex = EDIT_AREA_HELP_SCROLLING;
                                break;
                            case EDIT_CONTROL_VERTICAL_KNOB:
                                helpIndex = EDIT_AREA_HELP_SCROLLING;
                                break;
                            case EDIT_CONTROL_TERRAIN:
                                helpIndex = EDIT_AREA_HELP_TERRAIN;
                                break;
                            case EDIT_CONTROL_OBJECTS:
                                helpIndex = EDIT_AREA_HELP_OBJECTS;
                                break;
                            case EDIT_CONTROL_DETAILS:
                                helpIndex = EDIT_AREA_HELP_DETAILS;
                                break;
                            case EDIT_CONTROL_ERASER:
                                helpIndex = EDIT_AREA_HELP_ERASER;
                                break;
                            case EDIT_CONTROL_MAP:
                                helpIndex = EDIT_AREA_HELP_MAP;
                                break;
                        }
                        if (helpIndex >= 0)
                            NormalDialog(gEditAreaHelp[helpIndex], NORMAL_DIALOG_TYPE_QUICK_VIEW);
                    } else {
                        switch (message.id) {
                            case EDIT_CONTROL_RADAR:
                                DoRadar();
                                break;
                            case EDIT_CONTROL_HORIZONTAL_TRACK:
                            case EDIT_CONTROL_HORIZONTAL_KNOB:
                                DoHorizontalKnob();
                                break;
                            case EDIT_CONTROL_VERTICAL_TRACK:
                            case EDIT_CONTROL_VERTICAL_KNOB:
                                DoVerticalKnob();
                                break;
                        }
                    }
                    break;
            }
            return MESSAGE_DISPATCH_CONTINUE;
        case MESSAGE_KEY_DOWN:
            switch (message.keyCode) {
                case INPUT_SCAN_F3:
                    ScatterDetails();
                    DrawMap();
                    UpdateMapView();
                    break;
                case INPUT_SCAN_TAB:
                    SelectTool(((m_tool + 1) % EDIT_TOOL_COUNT));
                    break;
                case INPUT_SCAN_ESCAPE:
                    if (Confirm(localization::Tr("editor.quit.confirm")) == 1)
                        ShutDown(NULL);
                    else
                        return MESSAGE_DISPATCH_CONSUME;
                    break;
            }
            break;
    }
    return MESSAGE_DISPATCH_CONTINUE;
}

void editManager::SaveUndo(void) {
    memcpy(&m_undoMap, &m_map, sizeof(m_undoMap));
}

void editManager::UpdateMapView(void) {
    gWindowManager
        ->UpdateScreenRegion(EDIT_VIEW_LEFT, EDIT_VIEW_TOP, EDIT_VIEW_PIXELS, EDIT_VIEW_PIXELS);
}

void editManager::UpdateCursor(void) {
    DrawRulers(m_viewX, m_viewY, m_cursorX, m_cursorY);
}

void editManager::DrawRulers(i16 viewX, i16 viewY, i16 cursorX, i16 cursorY) {
    i16 mouseX;
    i16 mouseY;
    u8 color;
    char text[8];
    i16 i;

    gMouseManager->MouseCoords(mouseX, mouseY);
    if (mouseX < EDIT_VIEW_LEFT || mouseX >= EDIT_VIEW_LEFT + EDIT_VIEW_PIXELS
        || mouseY < EDIT_VIEW_TOP || mouseY > EDIT_VIEW_TOP + EDIT_VIEW_PIXELS) {
        cursorX = EDIT_NO_CELL;
        cursorY = EDIT_NO_CELL;
    }
    for (i = 0; i < EDIT_RULER_SLOTS; i++) {
        if (!m_zoomedOut && (i & 1))
            continue;
        if (!m_zoomedOut)
            m_buttons->DrawToBuffer(
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_LEFT,
                0,
                EDIT_FRAME_TOP_RULER_CELL,
                ICON_DRAW_NORMAL,
                ICON_DRAW_OFFSET_FULL
            );
        else
            m_buttons->DrawToBuffer(
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_LEFT,
                0,
                EDIT_FRAME_ZOOMED_RULER_CELL,
                ICON_DRAW_NORMAL,
                ICON_DRAW_OFFSET_FULL
            );
        sprintf(
            text,
            "%02d",
            viewX + i / (m_zoomedOut ? 1 : EDIT_RULER_SLOTS_PER_CELL)
        );
        if (i / (m_zoomedOut ? 1 : EDIT_RULER_SLOTS_PER_CELL) == cursorX)
            color = EDIT_RULER_CURSOR_COLOR;
        else
            color = EDIT_RULER_TEXT_COLOR;
        m_statusFont->DrawString(
            text,
            i * EDIT_RULER_SLOT_PIXELS
                + (m_zoomedOut ? 0 : EDIT_RULER_CELL_TEXT_OFFSET)
                + EDIT_TOP_RULER_TEXT_X,
            EDIT_TOP_RULER_TEXT_Y,
            color
        );
        if (!m_zoomedOut)
            m_buttons->DrawToBuffer(
                0,
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_TOP,
                EDIT_FRAME_LEFT_RULER_CELL,
                ICON_DRAW_NORMAL,
                ICON_DRAW_OFFSET_FULL
            );
        else
            m_buttons->DrawToBuffer(
                0,
                i * EDIT_RULER_SLOT_PIXELS + EDIT_VIEW_TOP,
                EDIT_FRAME_ZOOMED_RULER_CELL,
                ICON_DRAW_NORMAL,
                ICON_DRAW_OFFSET_FULL
            );
        sprintf(
            text,
            "%02d",
            viewY + i / (m_zoomedOut ? 1 : EDIT_RULER_SLOTS_PER_CELL)
        );
        if (i / (m_zoomedOut ? 1 : EDIT_RULER_SLOTS_PER_CELL) == cursorY)
            color = EDIT_RULER_CURSOR_COLOR;
        else
            color = EDIT_RULER_TEXT_COLOR;
        m_statusFont->DrawString(
            text,
            EDIT_LEFT_RULER_TEXT_X,
            i * EDIT_RULER_SLOT_PIXELS
                + (m_zoomedOut ? 0 : EDIT_RULER_CELL_TEXT_OFFSET)
                + EDIT_LEFT_RULER_TEXT_Y,
            color
        );
    }
    gWindowManager->UpdateScreenRegion(EDIT_VIEW_LEFT, 0, EDIT_VIEW_PIXELS, EDIT_VIEW_TOP);
    gWindowManager->UpdateScreenRegion(0, EDIT_VIEW_TOP, EDIT_VIEW_LEFT, EDIT_VIEW_PIXELS);
}

void editManager::ScreenToCell(i16& x, i16& y) {
    x -= EDIT_VIEW_LEFT;
    y -= EDIT_VIEW_TOP;
    switch (m_zoomedOut) {
        case EDIT_ZOOM_NORMAL:
            x /= EDIT_VIEW_CELL_PIXELS;
            y /= EDIT_VIEW_CELL_PIXELS;
            if (x > EDIT_VIEW_CELLS - 1)
                x = EDIT_VIEW_CELLS - 1;
            if (x < 0)
                x = 0;
            if (y > EDIT_VIEW_CELLS - 1)
                y = EDIT_VIEW_CELLS - 1;
            if (y < 0)
                y = 0;
            break;
        case EDIT_ZOOM_OUT:
            x /= EDIT_VIEW_ZOOMED_CELL_PIXELS;
            y /= EDIT_VIEW_ZOOMED_CELL_PIXELS;
            if (x > EDIT_VIEW_ZOOMED_CELLS - 1)
                x = EDIT_VIEW_ZOOMED_CELLS - 1;
            if (x < 0)
                x = 0;
            if (y > EDIT_VIEW_ZOOMED_CELLS - 1)
                y = EDIT_VIEW_ZOOMED_CELLS - 1;
            if (y < 0)
                y = 0;
            break;
    }
}

void editManager::DrawMap(void) {
    DrawView(m_viewX, m_viewY);
}

void editManager::DrawView(i16 viewX, i16 viewY) {
    i32 lineWidth;
    i32 cx;
    i32 cy;
    i32 cellPixels;
    i32 numCells;
    i32 savedZoom;

    savedZoom = m_zoomedOut;
    if (gGeneratingMaps)
        m_zoomedOut = EDIT_ZOOM_NORMAL;
    numCells = m_zoomedOut ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS;
    for (cy = 0; cy < numCells; cy++)
        for (cx = 0; cx < numCells; cx++)
            DrawCell(viewX + cx, viewY + cy, cx, cy, EDIT_DRAW_ALL);
    m_animationFrame++;
    m_animationFrame %= UPDATE_FRAME_CYCLE;
    cellPixels = m_zoomedOut ? EDIT_VIEW_ZOOMED_CELL_PIXELS
                                                       : EDIT_VIEW_CELL_PIXELS;
    lineWidth = m_zoomedOut ? 1 : EDIT_SELECTION_LINE_WIDTH;
    if (gSelectionX >= 0) {
        gSelectionColor = gMonoColorMap[EDIT_SELECTION_COLOR];
        FillBitmapArea(
            gWindowManager->m_screen,
            (gSelectionX - viewX) * cellPixels + EDIT_VIEW_LEFT,
            (gSelectionY - viewY) * cellPixels + EDIT_VIEW_TOP,
            lineWidth,
            gSelectionHeight * cellPixels - 1,
            gSelectionColor
        );
        FillBitmapArea(
            gWindowManager->m_screen,
            (gSelectionX - viewX) * cellPixels + EDIT_VIEW_LEFT,
            (gSelectionY - viewY) * cellPixels + EDIT_VIEW_TOP,
            gSelectionWidth * cellPixels - 1,
            lineWidth,
            gSelectionColor
        );
        FillBitmapArea(
            gWindowManager->m_screen,
            (gSelectionX - viewX + gSelectionWidth) * cellPixels + EDIT_VIEW_LEFT - lineWidth,
            (gSelectionY - viewY) * cellPixels + EDIT_VIEW_TOP,
            lineWidth,
            gSelectionHeight * cellPixels - 1,
            gSelectionColor
        );
        FillBitmapArea(
            gWindowManager->m_screen,
            (gSelectionX - viewX) * cellPixels + EDIT_VIEW_LEFT,
            (gSelectionY - viewY + gSelectionHeight) * cellPixels + EDIT_VIEW_TOP - lineWidth,
            gSelectionWidth * cellPixels - 1,
            lineWidth,
            gSelectionColor
        );
    }
    m_zoomedOut = savedZoom;
}

void editManager::DrawRadar(b32) {
    u8 color;
    i16 x;
    i16 y;
    icon* buttonsIcon;

    buttonsIcon = gResourceManager->GetIcon("buttons.icn");
    for (y = 0; y < MAP_CELL_GRID_SIZE; y++) {
        for (x = 0; x < MAP_CELL_GRID_SIZE; x++) {
            if (m_map.cells[x][y].m_objectIndex != MAP_CELL_NO_FRAME) {
                switch ((m_map.cells[x][y].m_objectTileset & MAP_CELL_TILESET_MASK)) {
                    case TILESET_MTN32:
                    case TILESET_TREE32:
                        color = gRadarTerrainColor[(m_map.cells[x][y].m_tileIndex / MAP_CELL_TILES_PER_TERRAIN)]
                                + RADAR_TERRAIN_SHADE;
                        break;
                    case TILESET_TOWN32:
                        color = EDIT_RADAR_TOWN_COLOR;
                        break;
                    case TILESET_RSRC32:
                        color = EDIT_RADAR_RESOURCE_COLOR;
                        break;
                    default:
                        color = gRadarTerrainColor[(m_map.cells[x][y].m_tileIndex / MAP_CELL_TILES_PER_TERRAIN)];
                        break;
                }
            } else {
                color = gRadarTerrainColor[(m_map.cells[x][y].m_tileIndex / MAP_CELL_TILES_PER_TERRAIN)];
            }
            if (gGeneratingMaps)
                color = EDIT_RADAR_UNSEEN_COLOR;
            buttonsIcon->FillToBuffer(
                x * RADAR_CELL_PIXELS + RADAR_LEFT,
                y * RADAR_CELL_PIXELS + RADAR_TOP,
                EDIT_FRAME_RADAR_CELL,
                color,
                ICON_DRAW_NORMAL,
                ICON_DRAW_OFFSET_FULL
            );
        }
    }
    buttonsIcon->FillToBuffer(
        m_viewX * RADAR_CELL_PIXELS + RADAR_LEFT,
        m_viewY * RADAR_CELL_PIXELS + RADAR_TOP,
        m_zoomedOut ? EDIT_FRAME_RADAR_ZOOMED_VIEW
                                              : EDIT_FRAME_RADAR_VIEW,
        RADAR_VIEWPORT_COLOR,
        ICON_DRAW_NORMAL,
        ICON_DRAW_OFFSET_FULL
    );
    gResourceManager->Dispose(buttonsIcon);
    gWindowManager->UpdateScreenRegion(RADAR_TOP, RADAR_LEFT, RADAR_SIZE, RADAR_SIZE);
    UpdateKnobs(1);
    UpdateCursor();
}

void editManager::DrawCell(i16 x, i16 y, i16 column, i16 row, u8 layers) {
    u8 tileset;
    u16 groundFrame;
    i16 screenX;
    i16 screenY;
    mapCell* cell;

    cell = &m_map.cells[x][y];
    screenX = column
                  * (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELL_PIXELS
                                                           : EDIT_VIEW_CELL_PIXELS)
              + EDIT_VIEW_LEFT;
    screenY = row
                  * (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELL_PIXELS
                                                           : EDIT_VIEW_CELL_PIXELS)
              + EDIT_VIEW_TOP;
    if (gGeneratingMaps) {
        if (layers & EDIT_DRAW_OVERLAY)
            TileToBitmap(
                m_cloudTiles[m_zoomedOut],
                (x + y) & EDIT_CLOUD_TILE_MASK,
                gWindowManager->m_screen,
                screenX,
                screenY
            );
        return;
    }
    if (layers & EDIT_DRAW_GROUND) {
        groundFrame = cell->m_flags;
        groundFrame <<= MAP_CELL_GROUND_FLIP_SHIFT;
        groundFrame |= cell->m_tileIndex & 0xff;
        TileToBitmap(
            m_groundTiles[m_zoomedOut],
            groundFrame,
            gWindowManager->m_screen,
            screenX,
            screenY
        );
    }
    if (layers & EDIT_DRAW_OBJECT) {
        if (cell->m_objectIndex != MAP_CELL_NO_FRAME) {
            tileset = (cell->m_objectTileset & MAP_CELL_TILESET_MASK);
            IconToBitmap(
                m_objectIcons[tileset][m_zoomedOut],
                gWindowManager->m_screen,
                screenX,
                screenY,
                cell->m_objectIndex,
                ICON_DRAW_OFFSET_FULL
            );
            if (cell->m_flags & MAP_CELL_OBJECT_ANIMATED)
                IconToBitmap(
                    m_objectIcons[tileset][m_zoomedOut],
                    gWindowManager->m_screen,
                    screenX,
                    screenY,
                    cell->m_objectIndex + m_animationFrame + 1,
                    ICON_DRAW_OFFSET_FULL
                );
        }
        if (cell->m_flags & MAP_CELL_OBJECT_EXTRA)
            IconToBitmap(
                m_objectIcons[TILESET_RSRC32][m_zoomedOut],
                gWindowManager->m_screen,
                screenX,
                screenY,
                cell->m_extraFrame,
                ICON_DRAW_OFFSET_FULL
            );
    }
    if (layers & EDIT_DRAW_OVERLAY) {
        if (cell->m_overlayIndex != MAP_CELL_NO_FRAME) {
            tileset = (cell->m_overlayTileset & MAP_CELL_TILESET_MASK);
            IconToBitmap(
                m_objectIcons[tileset][m_zoomedOut],
                gWindowManager->m_screen,
                screenX,
                screenY,
                cell->m_overlayIndex,
                ICON_DRAW_OFFSET_FULL
            );
            if (cell->m_flags & MAP_CELL_OVERLAY_ANIMATED)
                IconToBitmap(
                    m_objectIcons[tileset][m_zoomedOut],
                    gWindowManager->m_screen,
                    screenX,
                    screenY,
                    cell->m_overlayIndex + m_animationFrame + 1,
                    ICON_DRAW_OFFSET_FULL
                );
        }
    }
}

void editManager::ToggleZoom(void) {
    if (!m_zoomedOut) {
        m_zoomedOut = EDIT_ZOOM_OUT;
        Scroll(-10, -10);
    } else {
        m_zoomedOut = EDIT_ZOOM_NORMAL;
        Scroll(10, 10);
    }
    DrawView(m_viewX, m_viewY);
    DrawRadar(true);
    UpdateMapView();
}

void editManager::SelectTool(i16 tool) {
    i32 i;
    tag_message msg;

    if (m_tool == tool)
        return;
    if (m_toolManager) {
        gExec->RemoveManager(m_toolManager);
        delete m_toolManager;
        m_toolManager = NULL;
    }
    for (i = EDIT_TOOL_TERRAIN; i < EDIT_TOOL_COUNT; i++) {
        msg.type = MESSAGE_WIDGET;
        msg.id = i + EDIT_CONTROL_TERRAIN;
        msg.command = WIDGET_COMMAND_SET_FRAME;
        msg.value = (i == tool) + i * EDIT_FRAMES_PER_TOOL_BUTTON
                    + EDIT_FRAME_TOOL_BUTTONS;
        m_window->BroadcastMessage(msg);
    }
    switch (tool) {
        case EDIT_TOOL_TERRAIN:
            m_toolManager = new terrainManager;
            break;
        case EDIT_TOOL_OBJECTS:
            m_toolManager = new overlayManager;
            break;
        case EDIT_TOOL_DETAILS:
            m_toolManager = new eventsManager;
            break;
        case EDIT_TOOL_ERASER:
            m_toolManager = new clearManager;
            break;
    }
    if (m_toolManager) {
        if (!(gExec->AddManager(m_toolManager, BASE_MANAGER_PRIORITY_UNASSIGNED))) {
            m_tool = tool;
        } else {
            m_toolManager = NULL;
            m_tool = EDIT_TOOL_NONE;
        }
    } else {
        m_tool = EDIT_TOOL_NONE;
    }
    m_window->DrawWindow();
}

void editManager::Scroll(i16 dx, i16 dy) {
    m_viewX += dx;
    if (m_viewX < 0)
        m_viewX = 0;
    if (m_viewX
        > MAP_CELL_GRID_SIZE
              - (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS))
        m_viewX =
            MAP_CELL_GRID_SIZE
            - (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS);
    m_viewY += dy;
    if (m_viewY < 0)
        m_viewY = 0;
    if (m_viewY
        > MAP_CELL_GRID_SIZE
              - (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS))
        m_viewY =
            MAP_CELL_GRID_SIZE
            - (m_zoomedOut ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS);
    DrawView(m_viewX, m_viewY);
    UpdateMapView();
    DrawRadar(true);
}

void editManager::UpdateKnobs(i16 update) {
    double scaleX;
    double scaleY;
    i16 xPos;
    i16 yPos;

    scaleX =
        402.0
        / (m_zoomedOut ? EDIT_VIEW_ZOOMED_ORIGINS : EDIT_VIEW_ORIGINS);
    scaleY =
        402.0
        / (m_zoomedOut ? EDIT_VIEW_ZOOMED_ORIGINS : EDIT_VIEW_ORIGINS);
    xPos = m_viewX * scaleX;
    yPos = m_viewY * scaleY;
    m_horizontalKnob->m_x = xPos + EDIT_KNOB_FIRST;
    m_verticalKnob->m_y = yPos + EDIT_KNOB_FIRST;
    m_window->DrawWindow(update, EDIT_CONTROL_HORIZONTAL_TRACK, EDIT_CONTROL_SCROLL_DOWN_RIGHT);
}

void editManager::PaintGround(i16 column, i16 row, i16 width, i16 height, i16 terrain) {
    i16 startY;
    i16 startX;
    i32 redrawHeight;
    i32 j;
    i32 cellPixels;
    i32 redrawTop;
    i32 i;
    i32 redrawLeft;
    i32 redrawWidth;

    startX = m_viewX + column;
    startY = m_viewY + row;
    cellPixels =
        m_zoomedOut == EDIT_ZOOM_OUT ? EDIT_VIEW_ZOOMED_CELL_PIXELS : EDIT_VIEW_CELL_PIXELS;
    gEditManager->ClearArea(startX, startY, width, height, EDIT_CLEAR_ALL, false);
    for (i = 0; i < width; i++) {
        for (j = 0; j < height; j++) {
            m_map.cells[startX + i][startY + j].m_tileIndex = terrain * MAP_CELL_TILES_PER_TERRAIN;
            if (column + i
                    < (m_zoomedOut == EDIT_ZOOM_OUT ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS)
                && row + j
                       < (m_zoomedOut == EDIT_ZOOM_OUT ? EDIT_VIEW_ZOOMED_CELLS : EDIT_VIEW_CELLS))
                DrawCell(startX, startY, column + i, row + j, EDIT_DRAW_ALL);
        }
    }
    redrawLeft = column * cellPixels + EDIT_VIEW_LEFT;
    redrawWidth = width * cellPixels;
    if (redrawLeft + redrawWidth > LOGICAL_SCREEN_WIDTH - 1)
        redrawWidth = LOGICAL_SCREEN_WIDTH - 1 - redrawLeft;
    redrawTop = row * cellPixels + EDIT_VIEW_TOP;
    redrawHeight = height * cellPixels;
    if (redrawTop + redrawHeight > LOGICAL_SCREEN_HEIGHT - 1)
        redrawHeight = LOGICAL_SCREEN_HEIGHT - 1 - redrawTop;
    gWindowManager->UpdateScreenRegion(redrawLeft, redrawTop, redrawWidth, redrawHeight);
    DrawRadar(true);
}

void editManager::FillGround(i16 x, i16 y, i16 width, i16 height, i16 terrain) {
    i32 i;
    i32 j;

    gEditManager->ClearArea(x, y, width, height, EDIT_CLEAR_ALL, false);
    for (i = x; i < x + width; i++) {
        for (j = y; j < y + height; j++) {
            m_map.cells[i][j].m_tileIndex = terrain * MAP_CELL_TILES_PER_TERRAIN + Random(0, 3);
            m_map.cells[i][j].m_flags &= ~(MAP_CELL_OVERLAY_EXTRA | MAP_CELL_HERO_CURSOR);
        }
    }
}

void SetTileVariant(mapCell* cell, i32 firstTile) {
    if (cell->m_objectTileset
        && cell->m_tileIndex / MAP_CELL_TILES_PER_TERRAIN != firstTile / MAP_CELL_TILES_PER_TERRAIN)
        return;
    if (cell->m_tileIndex < firstTile || cell->m_tileIndex >= firstTile + TERRAIN_TILE_VARIANT_COUNT
        || gVaryTiles)
        cell->m_tileIndex = firstTile + Random(0, 3);
}

void editManager::BlendTerrain(
    i16 terrain,
    u8,
    u8 fromUndo,
    u8 skipBorders,
    u8 skipFill
) {
    u8 east;
    u8 ne;
    i32 terrainBase;
    i32 surrounding;
    u8 nw;
    i16 x;
    u8 se;
    i16 y;
    u8 south;
    u8 north;
    u8 sw;
    u8 west;
    mapCell* cell;
    i32 thisTerrain;

    surrounding = TERRAIN_WATER;
    if (skipFill)
        goto borders;
    for (y = 0; y < MAP_CELL_GRID_SIZE; y++) {
        for (x = 0; x < MAP_CELL_GRID_SIZE; x++) {
            if ((m_map.cells[x][y].m_tileIndex / MAP_CELL_TILES_PER_TERRAIN)
                == terrain) {
                north = south = east = west = nw = ne = sw = se = 0;
                if (y == 0 || CELL_TERRAIN(&m_map.cells[x][y - 1]) == terrain)
                    north = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x][y - 1]);
                if (y == MAP_CELL_GRID_SIZE || CELL_TERRAIN(&m_map.cells[x][y + 1]) == terrain)
                    south = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x][y + 1]);
                if (x == MAP_CELL_GRID_SIZE || CELL_TERRAIN(&m_map.cells[x + 1][y]) == terrain)
                    east = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x + 1][y]);
                if (x == 0 || CELL_TERRAIN(&m_map.cells[x - 1][y]) == terrain)
                    west = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x - 1][y]);
                if (!((north && west) || (north && east) || (south && west) || (south && east))) {
                    if (fromUndo)
                        m_map.cells[x][y].m_tileIndex =
                            (CELL_TERRAIN(&m_undoMap.cells[x][y]))
                            * MAP_CELL_TILES_PER_TERRAIN;
                    else
                        m_map.cells[x][y].m_tileIndex =
                            surrounding * MAP_CELL_TILES_PER_TERRAIN;
                }
                if (x == 0 || y == 0 || CELL_TERRAIN(&m_map.cells[x - 1][y - 1]) == terrain)
                    nw = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x - 1][y - 1]);
                if (x == 0 || y == MAP_CELL_GRID_SIZE
                    || CELL_TERRAIN(&m_map.cells[x - 1][y + 1]) == terrain)
                    sw = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x - 1][y + 1]);
                if (x == MAP_CELL_GRID_SIZE || y == MAP_CELL_GRID_SIZE
                    || CELL_TERRAIN(&m_map.cells[x + 1][y + 1]) == terrain)
                    se = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x + 1][y + 1]);
                if (x == MAP_CELL_GRID_SIZE || y == 0
                    || CELL_TERRAIN(&m_map.cells[x + 1][y - 1]) == terrain)
                    ne = 1;
                else
                    surrounding = CELL_TERRAIN(&m_map.cells[x + 1][y + 1]);
                if (!((north && ne && east) || (north && nw && west) || (south && se && east)
                      || (south && sw && west))
                    && !m_map.cells[x][y].m_objectTileset) {
                    if (fromUndo)
                        m_map.cells[x][y].m_tileIndex =
                            (CELL_TERRAIN(&m_undoMap.cells[x][y]))
                            * MAP_CELL_TILES_PER_TERRAIN;
                    else
                        m_map.cells[x][y].m_tileIndex =
                            surrounding * MAP_CELL_TILES_PER_TERRAIN;
                }
            }
        }
    }
borders:
    if (skipBorders)
        return;
    for (y = 0; y < MAP_CELL_GRID_SIZE; y++) {
        for (x = 0; x < MAP_CELL_GRID_SIZE; x++) {
            cell = &m_map.cells[x][y];
            thisTerrain =
                (cell->m_tileIndex / MAP_CELL_TILES_PER_TERRAIN);
            terrainBase = thisTerrain * MAP_CELL_TILES_PER_TERRAIN;
            north = south = east = west = 0;
            if (thisTerrain != TERRAIN_DIRT) {
                if (y > 0 && CELL_TERRAIN(&m_map.cells[x][y - 1]) != thisTerrain)
                    north = 1;
                if (y < MAP_CELL_GRID_SIZE - 1
                    && CELL_TERRAIN(&m_map.cells[x][y + 1]) != thisTerrain)
                    south = 1;
                if (x < MAP_CELL_GRID_SIZE - 1
                    && CELL_TERRAIN(&m_map.cells[x + 1][y]) != thisTerrain)
                    east = 1;
                if (x > 0 && CELL_TERRAIN(&m_map.cells[x - 1][y]) != thisTerrain)
                    west = 1;
                cell->m_flags &= ~(MAP_CELL_GROUND_FLIP_VERTICAL | MAP_CELL_GROUND_FLIP_HORIZONTAL);
                if (north) {
                    if (west) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_CORNER)
                        );
                        cell->m_flags |= MAP_CELL_GROUND_FLIP_HORIZONTAL;
                    } else if (east) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_CORNER)
                        );
                    } else {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EDGE)
                        );
                    }
                } else if (south) {
                    if (west) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_CORNER)
                        );
                        cell->m_flags |=
                            MAP_CELL_GROUND_FLIP_VERTICAL | MAP_CELL_GROUND_FLIP_HORIZONTAL;
                    } else if (east) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_CORNER)
                        );
                        cell->m_flags |= MAP_CELL_GROUND_FLIP_VERTICAL;
                    } else {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EDGE)
                        );
                        cell->m_flags |= MAP_CELL_GROUND_FLIP_VERTICAL;
                    }
                } else if (west) {
                    SetTileVariant(cell, terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_EAST_EDGE));
                    cell->m_flags |= MAP_CELL_GROUND_FLIP_HORIZONTAL;
                } else if (east) {
                    SetTileVariant(cell, terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_EAST_EDGE));
                }
                if (!(north | south | east | west)) {
                    if (x > 0 && y > 0 && CELL_TERRAIN(&m_map.cells[x - 1][y - 1]) != thisTerrain)
                        north = 1;
                    if (x < MAP_CELL_GRID_SIZE - 1 && y < MAP_CELL_GRID_SIZE - 1
                        && CELL_TERRAIN(&m_map.cells[x + 1][y + 1]) != thisTerrain)
                        south = 1;
                    if (x < MAP_CELL_GRID_SIZE - 1 && y > 0
                        && CELL_TERRAIN(&m_map.cells[x + 1][y - 1]) != thisTerrain)
                        east = 1;
                    if (x > 0 && y < MAP_CELL_GRID_SIZE - 1
                        && CELL_TERRAIN(&m_map.cells[x - 1][y + 1]) != thisTerrain)
                        west = 1;
                    if (north) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_INNER_CORNER)
                        );
                        cell->m_flags |= MAP_CELL_GROUND_FLIP_HORIZONTAL;
                    } else if (south) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_INNER_CORNER)
                        );
                        cell->m_flags |= MAP_CELL_GROUND_FLIP_VERTICAL;
                    } else if (east) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_INNER_CORNER)
                        );
                    } else if (west) {
                        SetTileVariant(
                            cell,
                            terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_NORTH_EAST_INNER_CORNER)
                        );
                        cell->m_flags |=
                            MAP_CELL_GROUND_FLIP_VERTICAL | MAP_CELL_GROUND_FLIP_HORIZONTAL;
                    } else {
                        SetTileVariant(cell, terrainBase + EDIT_TILE_RUN_FIRST(EDIT_TILE_PLAIN));
                    }
                }
            }
        }
    }
}

void editManager::DoRadar(void) {
    tag_message input;
    i16 x;
    tag_message mouseMove;
    i16 y;

    gMouseManager->MouseCoords(x, y);
    if (x < RADAR_LEFT || x > RADAR_LEFT + RADAR_SIZE || y < RADAR_TOP
        || y > RADAR_TOP + RADAR_SIZE)
        return;
    x = (x - RADAR_LEFT) / RADAR_CELL_PIXELS;
    y = (y - RADAR_TOP) / RADAR_CELL_PIXELS;
    switch (m_zoomedOut) {
        case EDIT_ZOOM_OUT:
            m_viewX = x - EDIT_VIEW_ZOOMED_CENTER;
            if (m_viewX + EDIT_VIEW_ZOOMED_CELLS > MAP_CELL_GRID_SIZE)
                m_viewX = MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS;
            m_viewY = y - EDIT_VIEW_ZOOMED_CENTER;
            if (m_viewY + EDIT_VIEW_ZOOMED_CELLS > MAP_CELL_GRID_SIZE)
                m_viewY = MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS;
            break;
        case EDIT_ZOOM_NORMAL:
            m_viewX = x - EDIT_VIEW_CENTER;
            if (m_viewX + EDIT_VIEW_CELLS > MAP_CELL_GRID_SIZE)
                m_viewX = MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS;
            m_viewY = y - EDIT_VIEW_CENTER;
            if (m_viewY + EDIT_VIEW_CELLS > MAP_CELL_GRID_SIZE)
                m_viewY = MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS;
            break;
    }
    if (m_viewX < 0)
        m_viewX = 0;
    if (m_viewY < 0)
        m_viewY = 0;
    DrawMap();
    DrawRadar(true);
    UpdateMapView();
    input = gInputManager->GetEvent();
    while (!IS_BUTTON_RELEASE_MESSAGE(input.type)) {
        Process1WindowsMessage();
        if (input.type == MESSAGE_MOUSE_MOVE) {
            while (input.type == MESSAGE_MOUSE_MOVE) {
                mouseMove = input;
                input = gInputManager->GetEvent();
            }
            gMouseManager->Main(mouseMove);
            x = (mouseMove.x - RADAR_LEFT) / RADAR_CELL_PIXELS;
            y = (mouseMove.y - RADAR_TOP) / RADAR_CELL_PIXELS;
            switch (m_zoomedOut) {
                case EDIT_ZOOM_OUT:
                    m_viewX = x - EDIT_VIEW_ZOOMED_CENTER;
                    if (m_viewX + EDIT_VIEW_ZOOMED_CELLS > MAP_CELL_GRID_SIZE)
                        m_viewX = MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS;
                    m_viewY = y - EDIT_VIEW_ZOOMED_CENTER;
                    if (m_viewY + EDIT_VIEW_ZOOMED_CELLS > MAP_CELL_GRID_SIZE)
                        m_viewY = MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS;
                    break;
                case EDIT_ZOOM_NORMAL:
                    m_viewX = x - EDIT_VIEW_CENTER;
                    if (m_viewX + EDIT_VIEW_CELLS > MAP_CELL_GRID_SIZE)
                        m_viewX = MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS;
                    m_viewY = y - EDIT_VIEW_CENTER;
                    if (m_viewY + EDIT_VIEW_CELLS > MAP_CELL_GRID_SIZE)
                        m_viewY = MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS;
                    break;
            }
            if (m_viewX < 0)
                m_viewX = 0;
            if (m_viewY < 0)
                m_viewY = 0;
            DrawMap();
            DrawRadar(true);
            UpdateMapView();
        } else {
            input = gInputManager->GetEvent();
        }
    }
}

void editManager::DoHorizontalKnob(void) {
    double scale;
    tag_message latest;
    i16 x;
    tag_message message;
    i16 y;
    i16 newX;

    gMouseManager->SetCursorShape(EDIT_CURSOR_HORIZONTAL_DRAG);
    scale =
        402.0
        / (m_zoomedOut ? EDIT_VIEW_ZOOMED_ORIGINS : EDIT_VIEW_ORIGINS);
    gMouseManager->MouseCoords(x, y);
    gInputManager->Flush();
    message.type = MESSAGE_MOUSE_MOVE;
    message.x = x;
    message.y = y;
    while (!IS_BUTTON_RELEASE_MESSAGE(message.type)) {
        Process1WindowsMessage();
        if (message.type == MESSAGE_MOUSE_MOVE) {
            latest = message;
            while (message.type == MESSAGE_MOUSE_MOVE) {
                latest = message;
                message = gInputManager->GetEvent();
            }
            if (latest.x < EDIT_KNOB_FIRST)
                latest.x = EDIT_KNOB_FIRST;
            if (latest.x > EDIT_KNOB_LAST)
                latest.x = EDIT_KNOB_LAST;
            gMouseManager->Main(latest);
            m_horizontalKnob->m_x = latest.x;
            newX = latest.x;
            newX = (newX - EDIT_KNOB_FIRST) / scale;
            if (m_viewX != newX) {
                if (newX
                    > (m_zoomedOut
                           ? MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS
                           : MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS))
                    newX = m_zoomedOut
                               ? MAP_CELL_GRID_SIZE - EDIT_VIEW_ZOOMED_CELLS
                               : MAP_CELL_GRID_SIZE - EDIT_VIEW_CELLS;
                if (newX < 0)
                    newX = 0;
                m_viewX = newX;
                DrawMap();
                UpdateMapView();
                DrawRadar(true);
            }
        } else {
            message = gInputManager->GetEvent();
        }
    }
    gMouseManager->SetCursorShape(EDIT_CURSOR_NORMAL);
    m_horizontalKnob->m_flags &= ~WIDGET_FLAG_SELECTED;
    m_horizontalTrack->m_flags &= ~WIDGET_FLAG_SELECTED;
}

